mapper.select:
select t.template_id as "templateId", t.business_type as "businessType", t.template_version as "templateVersion", t.effective_date as "effectiveDate", t.system_use_yn as "systemUseYn", t.status as "status", f.file_token as "fileToken", f.original_file_name as "originalFileName" from excel_upload_templates t left join excel_upload_template_files f on f.template_id = t.template_id
t.status != 'DELETED'
and t.business_type = #{businessType}
and t.effective_date <= CAST(#{effectiveDate} AS date)
order by t.effective_date desc, t.template_version desc limit #{limit} offset #{offset}

select upload_id as "uploadId", business_type as "businessType", template_id as "templateId", file_token as "fileToken", original_file_name as "originalFileName", validation_status as "validationStatus", uploader_user_id as "uploaderUserId", uploaded_at as "uploadedAt" from excel_upload_files
status != 'DELETED'
and business_type = #{businessType}
and upload_id = #{uploadId}
order by uploaded_at desc, upload_id limit #{limit} offset #{offset}

select h.upload_id as "uploadId", f.original_file_name as "originalFileName", h.total_count as "totalCount", h.success_count as "successCount", h.error_count as "errorCount", h.excluded_count as "excludedCount", h.saved_count as "savedCount", h.processing_time_millis as "processingTimeMillis", h.processed_at as "processedAt" from excel_upload_histories h join excel_upload_files f on f.upload_id = h.upload_id
h.status != 'DELETED'
and h.upload_id = #{uploadId}
and f.original_file_name ilike concat('%', #{originalFileName}, '%')
order by h.processed_at desc, h.upload_id limit #{limit} offset #{offset}

select download_id as "downloadId", requester_user_id as "requesterUserId", output_type as "outputType", query_condition::text as "queryCondition", data_scope_ref as "dataScopeRef", file_token as "fileToken", original_file_name as "originalFileName", requested_at as "requestedAt", generated_at as "generatedAt", status as "status" from excel_download_jobs
status != 'DELETED'
and requester_user_id = #{requesterUserId}
and output_type = #{outputType}
order by requested_at desc, download_id limit #{limit} offset #{offset}
